transforms.code:
if value['interval'] is not None:
	return value['interval']
else:
	if abs(system.date.daysBetween(value['dateRange']['startDate'], value['dateRange']['endDate'])) > 1:
		return "Days"

return "Hour"


oeeMetric = value['OEE Metric'].upper() if value.has_key('showOEEMetricSelector') and not value['showOEEMetricSelector'] else ''
assetPath = system.kanoa.utilities.formatPath(value['assetPath'], {}) if value['showAssetPath'] else ''
return '%s %s'%(system.kanoa.utilities.formatPath(assetPath, {}), oeeMetric)

if value['oeeMetric'] is None or value['thresholds'] is None or value['oeeMetric'] == 'all': return {}

if value['oeeMetric'] == 'availability': key = 'a'
elif value['oeeMetric'] == 'performance': key = 'p'
elif value['oeeMetric'] == 'quality': key = 'q'
elif value['oeeMetric'] == 'oee': key = 'oee'

ranges = [
			{"from": 0, "to": value['thresholds']['%s'%(key)] - value['thresholds']['%sTolerance'%(key)],	"color": "var(--kcBad)"}, 
			{"from": value['thresholds']['%s'%(key)] - value['thresholds']['%sTolerance'%(key)], "to": value['thresholds']['%s'%(key)], "color": "var(--kcOK)"}, 
			{"from": value['thresholds']['%s'%(key)], "to": 1.0, "color": "var(--kcGood)"}
		]

return {"ranges": ranges}

try:
	return value.rowCount > self.props.pager.initialOption
except:
	return False
